var n=`0497-maqluba`;var t=`world-0497`;var a=`JO`;var r=`western-asia`;var o=4;var l=89;var g={en:`Maqluba`,ua:`Маклюба`};var s={en:`A traditional dish from Jordan, centered on chicken thigh, yellow onion, white rice, potato. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Йорданія. Основні складники: куряче стегно, жовта цибуля, білий рис, картопля. Домашній варіант із кількостями продуктів за етапами приготування.`};var h=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`chicken-thigh`,780,`g`],[`yellow-onion`,180,`g`],[`extra-virgin-olive-oil`,45,`ml`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:12,i:[[`white-rice`,360,`g`],[`potato`,380,`g`],[`eggplant`,350,`g`],[`cauliflower`,300,`g`],[`ground-cinnamon`,3,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 50 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 50 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:50,i:[[`chicken-stock`,800,`ml`],[`allspice-berries`,5,`g`]]},{en:`Rest the tightly covered pot, then invert carefully onto a large plate so the rice-and-vegetable layers form a tower.`,ua:`Дайте закритій каструлі відпочити, а тоді обережно переверніть її на велику тарілку, щоб шари рису й овочів утворили вежу.`,t:[`rice-resting`,`fluffing-grains`],m:15,i:[]}];var d={slug:n,id:t,country:`JO`,region:r,servings:4,minutes:89,title:g,text:s,steps:h};export{a as country,d as default,t as id,l as minutes,r as region,o as servings,n as slug,h as steps,s as text,g as title};